package com.bank.covering.repository;

import com.bank.covering.dto.MiniStatementLine;
import com.bank.covering.model.Transaction;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import java.util.List;

public interface TransactionRepository extends JpaRepository<Transaction, String> {

    // Projection selects ONLY created_at and amount → all columns are in the
    // covering index ix_mini_statement → index-only scan, no heap fetch.
    @Query("SELECT new com.bank.covering.dto.MiniStatementLine(t.createdAt, t.amount) " +
           "FROM Transaction t WHERE t.accountId = :accountId ORDER BY t.createdAt DESC")
    List<MiniStatementLine> miniStatement(@Param("accountId") String accountId);
}
