package com.bank.covering.service;

import com.bank.covering.dto.MiniStatementLine;
import com.bank.covering.repository.TransactionRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.util.List;

@Service
public class MiniStatementService {
    private static final Logger log = LoggerFactory.getLogger(MiniStatementService.class);
    private final TransactionRepository repo;

    public MiniStatementService(TransactionRepository repo) { this.repo = repo; }

    public List<MiniStatementLine> recent(String accountId) {
        log.info("Mini-statement for {}: index-only scan on ix_mini_statement (no heap fetch)",
                 accountId);
        List<MiniStatementLine> lines = repo.miniStatement(accountId);
        log.info("Returned {} lines entirely from the covering index", lines.size());
        return lines;
    }
}
